-- Regulatory metadata mirrors the local development schema. No live integration is enabled.
alter table public.invoices add column invoice_kind text not null default 'simplified' check(invoice_kind in ('standard','simplified'));
alter table public.invoices add column document_code text not null default '388' check(document_code in ('388','381','383'));
alter table public.invoices add column environment text not null default 'legacy' check(environment in ('legacy','development','simulation','production'));
alter table public.invoices add column supply_date date;
alter table public.parties add column entity_type text not null default 'individual' check(entity_type in ('individual','business'));
alter table public.parties add column national_address jsonb not null default '{}'::jsonb;
alter table public.parties add column id_scheme text;
alter table public.parties add column id_number text;
alter table public.items add column tax_category text not null default 'S' check(tax_category in ('S','Z','E','O'));
alter table public.items add column exemption_code text not null default '';
alter table public.items add column exemption_reason text not null default '';
alter table public.invoice_lines add column tax_category text not null default 'S' check(tax_category in ('S','Z','E','O'));
alter table public.invoice_lines add column exemption_code text not null default '';
alter table public.invoice_lines add column exemption_reason text not null default '';
alter table public.invoice_lines add column unit_code text not null default 'PCE';
create table public.invoice_documents(organization_id uuid not null,invoice_id uuid not null,kind text not null check(kind in ('xml_candidate','signed_xml','cleared_xml')),content text not null,sha256 text not null,created_at timestamptz not null default now(),primary key(organization_id,invoice_id,kind),foreign key(organization_id,invoice_id) references public.invoices(organization_id,id));
create table public.invoice_tax_totals(organization_id uuid not null,invoice_id uuid not null,tax_category text not null,vat_rate numeric(5,2) not null,exemption_code text not null default '',exemption_reason text not null default '',taxable bigint not null check(taxable>=0),vat bigint not null check(vat>=0),primary key(organization_id,invoice_id,tax_category,vat_rate,exemption_code),foreign key(organization_id,invoice_id) references public.invoices(organization_id,id));
create table public.regulatory_queue(organization_id uuid not null,invoice_id uuid not null,operation text not null check(operation in ('reporting','clearance')),state text not null default 'blocked',attempts integer not null default 0,last_error text,last_response jsonb,updated_at timestamptz not null default now(),primary key(organization_id,invoice_id),foreign key(organization_id,invoice_id) references public.invoices(organization_id,id));
create table public.audit_events(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),installation_id uuid not null,local_id bigint not null,event text not null,details jsonb not null,previous_hash text not null,hash text not null,created_at timestamptz not null,unique(organization_id,installation_id,local_id),foreign key(organization_id,installation_id) references public.installations(organization_id,id));
alter table public.invoice_documents enable row level security;
revoke all on public.invoice_documents from anon,authenticated;
grant select on public.invoice_documents to authenticated;
grant all on public.invoice_documents to service_role;
create policy invoice_documents_managers on public.invoice_documents for select to authenticated using(private.has_org_role(organization_id,array['owner','accountant']));
alter table public.invoice_tax_totals enable row level security;
revoke all on public.invoice_tax_totals from anon,authenticated;
grant select on public.invoice_tax_totals to authenticated;
grant all on public.invoice_tax_totals to service_role;
create policy invoice_tax_totals_managers on public.invoice_tax_totals for select to authenticated using(private.has_org_role(organization_id,array['owner','accountant']));
alter table public.regulatory_queue enable row level security;
revoke all on public.regulatory_queue from anon,authenticated;
grant select on public.regulatory_queue to authenticated;
grant all on public.regulatory_queue to service_role;
create policy regulatory_queue_managers on public.regulatory_queue for select to authenticated using(private.has_org_role(organization_id,array['owner','accountant']));
alter table public.audit_events enable row level security;
revoke all on public.audit_events from anon,authenticated;
grant select on public.audit_events to authenticated;
grant all on public.audit_events to service_role;
create policy audit_events_managers on public.audit_events for select to authenticated using(private.has_org_role(organization_id,array['owner','accountant']));
create trigger invoice_documents_immutable before update or delete on public.invoice_documents for each row execute function private.reject_ledger_edit();
create trigger invoice_tax_totals_immutable before update or delete on public.invoice_tax_totals for each row execute function private.reject_ledger_edit();
create trigger audit_events_immutable before update or delete on public.audit_events for each row execute function private.reject_ledger_edit();
